using System.Text.RegularExpressions;

namespace GameLog.Application.Common;

/// <summary>Storage keys are generated by the server and checked again wherever a client can name one.</summary>
public static partial class ObjectKeys
{
    [GeneratedRegex("^[a-z0-9]+(/[a-z0-9][a-z0-9._-]*)+$")]
    private static partial Regex Pattern();

    public static bool IsValid(string? key) =>
        !string.IsNullOrEmpty(key) && key.Length <= 200 && Pattern().IsMatch(key) && !key.Contains("..");

    /// <summary>"avatars" + "webp" -> "avatars/3f2a...c9.webp" (unguessable, never derived from user input).</summary>
    public static string New(string folder, string extension) => $"{folder}/{Guid.NewGuid():N}.{extension}";

    public static string ContentTypeFor(string key) => Path.GetExtension(key).ToLowerInvariant() switch
    {
        ".webp" => "image/webp",
        ".jpg" or ".jpeg" => "image/jpeg",
        ".png" => "image/png",
        _ => "application/octet-stream",
    };
}
